def compute(vars):
    federal_nol = vars["v1"]
    foreign_nol = vars["v2"]

    if foreign_nol == 0:
        return None

    ratio = federal_nol / foreign_nol
    percentage = round(ratio * 100, 3)

    return {
        "value": percentage,
        "trace": {
            "federal_nol": federal_nol,
            "foreign_nol": foreign_nol,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
